/**
 * 로고 컴포넌트 — 기획서 8장 브랜드 아이덴티티 웹 적용 가이드
 *
 * 이 컴포넌트는 CI 가이드의 금지 사항(8.6)을 코드 구조로 강제한다.
 *
 *  - 색상: 승인된 3색 외에는 타입 시스템이 거부한다. `currentColor` 를 쓰지 않는다
 *          (부모 color 상속으로 임의 색이 적용되는 사고 방지 — 8.6)
 *  - 비율: viewBox 만 지정하고 width/height 를 개별 지정하지 않는다.
 *          호출부는 폭만 주고 높이는 aspect-ratio 로 따라온다 (비율 왜곡 금지 — 8.6)
 *  - 회전: 이 컴포넌트에 회전 관련 prop 자체를 두지 않는다 (회전 금지 — 8.6)
 *  - 효과: drop-shadow / stroke / opacity 상시 적용 금지 — 8.6
 *  - 접근성: role="img" + <title> 로 "플럭스랩스" 제공 — 8.6
 *
 * ⚠️ 전달받은 SVG 원본 15종의 blue 값은 `#191970` 으로, 기획서 8.2 및 CI 컬러
 *    시스템 가이드가 지정한 Flux Navy `#2A4269` 와 다르다. 본 구현은 문서상
 *    브랜드 지정 컬러(#2A4269)를 따랐다. 디자이너 확인 필요.
 *    → docs/open-questions.md 참조
 */

/** 승인된 로고 컬러. 이 3색 외에는 사용 금지 (기획서 8.2) */
const LOGO_FILL = {
  navy: "#2A4269",
  white: "#FFFFFF",
  black: "#000000",
} as const;

export type LogoTone = keyof typeof LOGO_FILL;

/** 형태별 실측 비율 (기획서 8.1) — 잉크 영역 bounding box 기준 */
const VIEWBOX = {
  primary: "0 0 478 73", // 6.55 : 1
  compact: "0 0 361 151", // 2.39 : 1
  symbol: "0 0 130 196", // 1 : 1.51 (2:3) — 정사각형이 아니다
} as const;

export type LogoVariant = keyof typeof VIEWBOX;

/** 웹 권장 최소 사이즈 (기획서 8.5) — 개발 중 실수 감지용 */
const MIN_WIDTH: Record<LogoVariant, number> = {
  primary: 110,
  compact: 120,
  symbol: 24,
};

type LogoProps = {
  variant?: LogoVariant;
  tone?: LogoTone;
  /** 가로폭(px). 높이는 비율에 따라 자동 결정된다 */
  width: number;
  className?: string;
  /** 로고가 링크 안에 있어 상위에서 이미 라벨을 제공하는 경우 true */
  decorative?: boolean;
};

export function Logo({
  variant = "primary",
  tone = "navy",
  width,
  className,
  decorative = false,
}: LogoProps) {
  if (process.env.NODE_ENV !== "production" && width < MIN_WIDTH[variant]) {
    console.warn(
      `[Logo] ${variant} 로고의 웹 권장 최소 폭은 ${MIN_WIDTH[variant]}px 입니다 (지정값 ${width}px). 기획서 8.5 참조.`,
    );
  }

  const a11y = decorative
    ? ({ "aria-hidden": true } as const)
    : ({ role: "img", "aria-label": "플럭스랩스" } as const);

  return (
    <svg
      viewBox={VIEWBOX[variant]}
      // width 만 지정한다. height 는 viewBox 비율에 따라 자동 결정된다.
      // width/height 를 개별 지정하면 비율이 왜곡될 수 있다 (8.6)
      width={width}
      className={`h-auto ${className ?? ""}`}
      // fill 은 CSS 변수를 거쳐 .logo-path 에 주입된다. 값은 위 LOGO_FILL 상수뿐이다.
      style={{ ["--logo-fill" as string]: LOGO_FILL[tone] }}
      xmlns="http://www.w3.org/2000/svg"
      {...a11y}
    >
      {!decorative && <title>플럭스랩스</title>}
      {variant === "primary" && <PrimaryPaths />}
      {variant === "compact" && <CompactPaths />}
      {variant === "symbol" && <SymbolPaths />}
    </svg>
  );
}

